# Brightwood Tracker (M20)
# {5}{G}, {T}: Look at the top four cards of your library. You may reveal a creature card from
# among them and put it into your hand. Put the rest on the bottom of your library in a random order.

_top_of_library = (Zone(kind=ZoneKind.LIBRARY, controller=ControllerRef.YOU, position=ZonePosition.TOP),)

tracker = ActivatedAbility(
    cost=Cost(
        parts=(
            CostManaColor(color='G', amount=QConst(value=1)),
            CostManaGeneric(amount=QConst(value=5)),
            CostTap(),
        ),
    ),
    effect=Seq(
        steps=(
            A(Verb.LOOK_AT, {'controller': ControllerRef.YOU, 'count': QConst(value=4)}),
            OptionalEffect(
                inner=Seq(
                    steps=(
                        A(Verb.REVEAL, {'controller': ControllerRef.YOU, 'count': QConst(value=1)}),
                        A(Verb.MOVE_ZONE, {
                            'cards': Selector(
                                count=QConst(value=1),
                                mode=SelectorMode.ONE_OF,
                                filter=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                                zones=_top_of_library,
                            ),
                            'destination': Zone(kind=ZoneKind.HAND, controller=ControllerRef.YOU),
                        }),
                    ),
                ),
            ),
            A(Verb.MOVE_ZONE, {
                'cards': Selector(
                    count=QConst(value=1),
                    mode=SelectorMode.REST,
                    filter=FAnd(children=()),
                    zones=_top_of_library,
                ),
                'destination': Zone(
                    kind=ZoneKind.LIBRARY,
                    controller=ControllerRef.YOU,
                    position=ZonePosition.BOTTOM,
                ),
            }),
        ),
    ),
)

abilities = [tracker, *compiled]
